#define N 5

// Static array declaration
int data[N] = {10, 20, 30, 40, 50};

// Read access (Index 0 is the first element)
int first = data[0];       // 10

// Write access
data[2] = 99;

// Array access vs. Pointer arithmetic (Equivalent)
int third_val = data[2];
int third_ptr = *(data + 2); // Also 99

// Array names decay to pointers to the first element
int* p = data;
int last_val = p[N - 1];   // 50

// Danger: data[N] is out of bounds
// data[N] = -1; // Undefined Behavior
